draw:
var g = 9.8, h = p.h, e = p.e;
var floorY = H - 26, topY = 30;
var sc = (floorY - topY) / h;
var tf = Math.sqrt(2 * h / g);
var total = tf + 2 * tf * e / (1 - e) + 0.6;
var tt = t % total;
var y = 0, n = 0, peak = h;
if (tt < tf) { y = h - 0.5 * g * tt * tt; n = 0; peak = h; }
else {
  var rem = tt - tf, vn = g * tf * e;
  n = 1; peak = vn * vn / (2 * g); y = 0;
  for (var i = 0; i < 80; i++) {
    var dur = 2 * vn / g;
    if (rem < dur) { y = vn * rem - 0.5 * g * rem * rem; peak = vn * vn / (2 * g); n = i + 1; break; }
    rem -= dur; vn *= e; n = i + 2; peak = vn * vn / (2 * g); y = 0;
  }
}
if (y < 0) y = 0;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(0, floorY); ctx.lineTo(W, floorY); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("floor", 6, floorY + 15);

var bx = W * 0.34;

ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(W * 0.10, floorY - h * sc); ctx.lineTo(W * 0.78, floorY - h * sc); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("drop height h = " + h.toFixed(2) + " m", W * 0.80, floorY - h * sc + 4);

var k;
for (k = 1; k <= 5; k++) {
  var hk = h * Math.pow(e, 2 * k);
  if (hk * sc < 4) break;
  ctx.strokeStyle = C.rule;
  ctx.setLineDash([2, 4]);
  ctx.beginPath(); ctx.moveTo(W * 0.62, floorY - hk * sc); ctx.lineTo(W * 0.78, floorY - hk * sc); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.faint;
  ctx.fillText("bounce " + k + ": " + hk.toFixed(2) + " m", W * 0.80, floorY - hk * sc + 4);
}

ctx.strokeStyle = C.accent;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(W * 0.16, floorY - peak * sc); ctx.lineTo(W * 0.56, floorY - peak * sc); ctx.stroke();
ctx.setLineDash([]);

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(W * 0.14, floorY); ctx.lineTo(W * 0.14, floorY - peak * sc); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "right";
ctx.fillText("current peak", W * 0.12, floorY - peak * sc / 2);

ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(bx, floorY - y * sc - 9, 9, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("e = " + e.toFixed(2) + "  so each bounce keeps e squared = " + (e * e).toFixed(3) + " of the height", 6, 16);

var totalDist = h * (1 + e * e) / (1 - e * e);
out.note = "bounce " + n + ", peak " + peak.toFixed(3) + " m, total path over all bounces " + totalDist.toFixed(2) + " m";

var m1 = p.ratio, m2 = 1, u = 5;
var thMaxDeg = 180;
if (m1 > m2) thMaxDeg = Math.asin(m2 / m1) * 180 / Math.PI;
var thDeg = p.theta;
if (thDeg > thMaxDeg - 0.5) thDeg = thMaxDeg - 0.5;
if (thDeg < 1) thDeg = 1;
var th = thDeg * Math.PI / 180;

var disc = m2 * m2 - m1 * m1 * Math.sin(th) * Math.sin(th);
if (disc < 0) disc = 0;
var v1 = u * (m1 * Math.cos(th) + Math.sqrt(disc)) / (m1 + m2);
var p1x = m1 * v1 * Math.cos(th), p1y = m1 * v1 * Math.sin(th);
var p2x = m1 * u - p1x, p2y = -p1y;
var v2 = Math.sqrt(p2x * p2x + p2y * p2y) / m2;
var th2 = Math.atan2(-p2y, p2x);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.4;

var cx = W * 0.28, cy = H * 0.56;
var vs = 11;
var cycle = 3.4, tHit = 1.5;
var now = t % cycle;

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var a = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * Math.cos(a - 0.4), y1 - 7 * Math.sin(a - 0.4));
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * Math.cos(a + 0.4), y1 - 7 * Math.sin(a + 0.4));
  ctx.stroke();
}

ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(cx - W * 0.22, cy); ctx.lineTo(cx + W * 0.30, cy); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + Math.cos(th) * W * 0.26, cy - Math.sin(th) * W * 0.26); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + Math.cos(th2) * W * 0.26, cy + Math.sin(th2) * W * 0.26); ctx.stroke();
ctx.setLineDash([]);

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(cx, cy, 26, -th, 0); ctx.stroke();
ctx.beginPath(); ctx.arc(cx, cy, 38, 0, th2); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("th1 " + thDeg.toFixed(0) + " deg", cx + 30, cy - 14);
ctx.fillText("th2 " + (th2 * 180 / Math.PI).toFixed(0) + " deg", cx + 42, cy + 26);

var x1, y1, x2, y2;
if (now < tHit) {
  x1 = cx - (tHit - now) * u * vs; y1 = cy;
  x2 = cx; y2 = cy;
  arrow(x1 - 34, y1, x1 - 12, y1, C.ink);
  ctx.fillStyle = C.ink; ctx.textAlign = "center";
  ctx.fillText("u = 5.0 m/s", x1 - 23, y1 - 10);
} else {
  var af = now - tHit;
  x1 = cx + v1 * Math.cos(th) * vs * af; y1 = cy - v1 * Math.sin(th) * vs * af;
  x2 = cx + v2 * Math.cos(th2) * vs * af; y2 = cy + v2 * Math.sin(th2) * vs * af;
}

var r1 = 7 + 4 * Math.sqrt(m1), r2 = 7 + 4 * Math.sqrt(m2);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(x1, y1, r1, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(x2, y2, r2, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("m1", x1, y1 - r1 - 5);
ctx.fillText("m2", x2, y2 + r2 + 13);

ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("mass ratio m1/m2 = " + m1.toFixed(1), 6, 16);

var ox = W * 0.70, oy = H * 0.30;
var L = W * 0.24;
var psc = L / (m1 * u);
arrow(ox, oy, ox + m1 * u * psc, oy, C.faint);
ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("p before", ox + m1 * u * psc / 2, oy - 8);

var hx = ox + p1x * psc, hy = oy - p1y * psc;
arrow(ox, oy, hx, hy, C.figure);
ctx.fillStyle = C.figure;
ctx.textAlign = "right";
ctx.fillText("p1 after", hx - 6, hy - 4);

arrow(hx, hy, ox + m1 * u * psc, oy, C.accent);
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("p2 after", hx + 10, hy + 16);

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("the two after-arrows must close on the before-arrow", ox + m1 * u * psc / 2, oy + H * 0.30);

var note = "v1 = " + v1.toFixed(2) + " m/s at " + thDeg.toFixed(0) + " deg, v2 = " + v2.toFixed(2) + " m/s at " + (th2 * 180 / Math.PI).toFixed(0) + " deg";
if (m1 > m2) note = note + "  |  max deflection of m1 = " + thMaxDeg.toFixed(1) + " deg";
out.note = note;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.4;
ctx.textAlign = "center";

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var a = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * Math.cos(a - 0.4), y1 - 7 * Math.sin(a - 0.4));
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * Math.cos(a + 0.4), y1 - 7 * Math.sin(a + 0.4));
  ctx.stroke();
}

ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(W * 0.5, 6); ctx.lineTo(W * 0.5, H - 6); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.ink;
ctx.fillText("STAGE 1: the bang  -  use momentum", W * 0.25, 18);
ctx.fillText("STAGE 2: the swing  -  use energy", W * 0.75, 18);

var pivx = W * 0.25, pivy = 34;
var Lr = H * 0.46;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(pivx - 30, pivy); ctx.lineTo(pivx + 30, pivy); ctx.stroke();
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(pivx, pivy); ctx.lineTo(pivx, pivy + Lr); ctx.stroke();

var bw = 26;
ctx.fillStyle = C.figure;
ctx.fillRect(pivx - bw / 2, pivy + Lr, bw, bw);
ctx.fillStyle = C.paper;
ctx.fillText("M", pivx, pivy + Lr + 17);

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(pivx - 60, pivy + Lr + bw / 2, 5, 0, Math.PI * 2); ctx.fill();
arrow(pivx - 54, pivy + Lr + bw / 2, pivx - 22, pivy + Lr + bw / 2, C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("m, speed v", pivx - 60, pivy + Lr - 8);

ctx.fillStyle = C.ink;
ctx.fillText("m v = (m + M) V", W * 0.25, pivy + Lr + 48);
ctx.fillStyle = C.faint;
ctx.fillText("energy is NOT conserved here", W * 0.25, pivy + Lr + 66);

var pv2 = W * 0.75;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(pv2 - 30, pivy); ctx.lineTo(pv2 + 30, pivy); ctx.stroke();
var ang = 0.62;
var ex = pv2 + Lr * Math.sin(ang), ey = pivy + Lr * Math.cos(ang);
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(pv2, pivy); ctx.lineTo(pv2, pivy + Lr); ctx.stroke();
ctx.setLineDash([]);
ctx.strokeStyle = C.figure;
ctx.beginPath(); ctx.moveTo(pv2, pivy); ctx.lineTo(ex, ey); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillRect(ex - bw / 2, ey, bw, bw);
ctx.fillStyle = C.paper;
ctx.fillText("m+M", ex, ey + 17);

ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(pv2 - 40, pivy + Lr); ctx.lineTo(ex + 40, pivy + Lr); ctx.stroke();
ctx.beginPath(); ctx.moveTo(ex + 40, ey); ctx.lineTo(ex, ey); ctx.stroke();
ctx.setLineDash([]);
arrow(ex + 34, pivy + Lr, ex + 34, ey + 2, C.accent);
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("h", ex + 40, (ey + pivy + Lr) / 2);

ctx.textAlign = "center";
ctx.fillStyle = C.ink;
ctx.fillText("half V squared = g h", pv2, pivy + Lr + 48);
ctx.fillStyle = C.faint;
ctx.fillText("V from stage 1 is the only link", pv2, pivy + Lr + 66);
